package com.example.backend.service;
import com.example.backend.entity.RefreshToken; import com.example.backend.entity.User; import com.example.backend.repository.RefreshTokenRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.time.Instant; import java.util.Base64;
@Service public class RefreshTokenService { private final RefreshTokenRepository repository; private final SecureRandom random=new SecureRandom(); @Value("${refresh.expiration-ms:604800000}") private long expirationMs; public RefreshTokenService(RefreshTokenRepository repository){this.repository=repository;} public record IssuedToken(User user,String value){}
 @Transactional public IssuedToken issue(User user){byte[] bytes=new byte[32];random.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);repository.save(new RefreshToken(user,digest(raw),Instant.now().plusMillis(expirationMs)));return new IssuedToken(user,raw);}
 @Transactional public IssuedToken rotate(String raw){if(raw==null||raw.isBlank())throw invalid();String hash=digest(raw);RefreshToken stored=repository.findByTokenHash(hash).orElseThrow(RefreshTokenService::invalid);repository.delete(stored);if(stored.getExpiresAt().isBefore(Instant.now()))throw invalid();return issue(stored.getUser());}
 @Transactional public void revoke(String raw){if(raw!=null&&!raw.isBlank())repository.deleteByTokenHash(digest(raw));}
 private static String digest(String value){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private static ResponseStatusException invalid(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh token is invalid or expired");} }
